<script setup lang="ts">
import {ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {api} from '../api';import {saveSession} from '../auth';import {clearProject} from '../projects';import {KeyRound,LoaderCircle,ShieldCheck} from 'lucide-vue-next'
const route=useRoute(),router=useRouter(),loading=ref(false),error=ref('')
// 登录页始终使用空白表单，账号密码由用户正常输入，不在前端保存任何默认凭据。
const form=ref({email:'',password:''})
async function submit(){error.value='';loading.value=true;try{const {data}=await api.post('/auth/login',form.value);clearProject();saveSession(data.access_token,data.user,data.refresh_token);await router.replace(String(route.query.redirect||'/'))}catch(e:any){error.value=e.response?.data?.detail||'无法登录，请检查账号或API服务'}finally{loading.value=false}}
</script>
<template><main class="login-page"><section class="login-card"><div class="login-brand"><div class="brand-mark">Q</div><div><strong>QuantForge</strong><small>SECURE RESEARCH PLATFORM</small></div></div><div class="login-icon"><ShieldCheck :size="28"/></div><h1>登录研究工作台</h1><p>身份验证后才能访问项目内的数据、模型和回测产物。</p><form @submit.prevent="submit"><div class="field"><label for="login-email">邮箱</label><input id="login-email" v-model="form.email" type="email" autocomplete="username" required/></div><div class="field"><label for="login-password">密码</label><input id="login-password" v-model="form.password" type="password" autocomplete="current-password" required minlength="8"/></div><p v-if="error" class="error-box">{{error}}</p><button class="primary login-submit" :disabled="loading"><LoaderCircle v-if="loading" :size="17" class="spin"/><KeyRound v-else :size="17"/>{{loading?'正在验证':'登录'}}</button></form></section></main></template>
